"use strict";(globalThis.webpackChunkeo_glossary=globalThis.webpackChunkeo_glossary||[]).push([[73273],{72089(e){e.exports=JSON.parse('{"tag":{"label":"WGCapD","permalink":"/eo-glossary/tags/wg-cap-d","allTagsPath":"/eo-glossary/tags","count":28,"items":[{"id":"terms/accessibility","title":"Accessibility","description":"The capability to access available data.","permalink":"/eo-glossary/terms/accessibility"},{"id":"terms/citizen_data_scientist","title":"Citizen Data Scientist","description":"A person who creates or generates models that leverage predictive or prescriptive analytics, but whose primary job function is outside of the field of statistics and analytics.","permalink":"/eo-glossary/terms/citizen_data_scientist"},{"id":"terms/data_colonialism","title":"Data Colonialism","description":"The process by which governments, non-governmental organizations and corporations claim ownership of and privatize the data that is produced by their users and citizens.","permalink":"/eo-glossary/terms/data_colonialism"},{"id":"terms/data_democracy","title":"Data Democracy","description":"Describes a methodological framework of values and actions that benefit and minimize any harm to the public or the typical user.","permalink":"/eo-glossary/terms/data_democracy"},{"id":"terms/data_licencing","title":"Data Licencing","description":"Legal instrument by which a copyright holder may grant rights over the protected work.","permalink":"/eo-glossary/terms/data_licencing"},{"id":"terms/data_licensing","title":"Data Licensing","description":"Legal instrument granting rights to use protected data, where open data requires an explicitly applied license conforming to the Open Definition.","permalink":"/eo-glossary/terms/data_licensing"},{"id":"terms/data_user_guide","title":"Data User Guide","description":"A document, either on-line or hardcopy, containing the necessary information for the correct usage of the data.","permalink":"/eo-glossary/terms/data_user_guide"},{"id":"terms/discipline","title":"Discipline","description":"A field of study such as oceanography, meteorology, geology, or marine biology.","permalink":"/eo-glossary/terms/discipline"},{"id":"terms/domain_expert","title":"Domain Expert","description":"Subject-matter expert with authoritative knowledge in a specific domain, especially in expert systems development.","permalink":"/eo-glossary/terms/domain_expert"},{"id":"terms/eo_space_data_users","title":"EO Space Data Users","description":"User communities that rely on Earth Observation space data and products for application areas such as climate monitoring, agriculture, or disaster response.","permalink":"/eo-glossary/terms/eo_space_data_users"},{"id":"terms/guide","title":"Guide","description":"The guide function is part of the user information function to provide information about satellites, sensors, product types and services.","permalink":"/eo-glossary/terms/guide"},{"id":"terms/impact","title":"Impact","description":"Regarded long-term according to X.","permalink":"/eo-glossary/terms/impact"},{"id":"terms/open_access","title":"Open Access","description":"Principle that published research outputs, especially from publicly-funded work, should be freely accessible to all without subscription barriers.","permalink":"/eo-glossary/terms/open_access"},{"id":"terms/open_data","title":"Open Data","description":"Data freely accessible, usable, modifiable, and shareable for any purpose, subject only to attribution or share-alike requirements, as defined by the Open Definition.","permalink":"/eo-glossary/terms/open_data"},{"id":"terms/open_science","title":"Open Science","description":"Practice of science adhering to open principles, including open access publishing, sharing research data and source code as open data, and using open-source tools.","permalink":"/eo-glossary/terms/open_science"},{"id":"terms/open_source","title":"Open Source","description":"Software with source code available under an open license, permitting free use, inspection, modification, and redistribution by users with technical capability.","permalink":"/eo-glossary/terms/open_source"},{"id":"terms/outcome","title":"Outcome","description":"### Notes.","permalink":"/eo-glossary/terms/outcome"},{"id":"terms/outreach","title":"Outreach","description":"The act of inviting users (or stakeholders more broadly) to engage in a mutually beneficial exchange.","permalink":"/eo-glossary/terms/outreach"},{"id":"terms/policy","title":"Policy","description":"Deliberate system of guidelines to guide decisions and achieve rational outcomes.","permalink":"/eo-glossary/terms/policy"},{"id":"terms/policy_cycle","title":"Policy Cycle","description":"Well-established concept, typically taught as the rational model of policy decision-making.","permalink":"/eo-glossary/terms/policy_cycle"},{"id":"terms/policy_file","title":"Policy File","description":"Policy documents that represent the official written reference for a given Policy.","permalink":"/eo-glossary/terms/policy_file"},{"id":"terms/policy_making","title":"Policy Making","description":"Process by which governments translate their political vision into programmes and actions to deliver outcomes \u2014 desired change in the real world.","permalink":"/eo-glossary/terms/policy_making"},{"id":"terms/policy_milestone","title":"Policy Milestone","description":"Markers of significant progress in addressing specific issues, or crucial decision points where significant choices are made.","permalink":"/eo-glossary/terms/policy_milestone"},{"id":"terms/policy_objective","title":"Policy Objective","description":"Desired outcome that policymakers wish to achieve.","permalink":"/eo-glossary/terms/policy_objective"},{"id":"terms/policy_target","title":"Policy Target","description":"Specific level or rate set for the Policy Objective.","permalink":"/eo-glossary/terms/policy_target"},{"id":"terms/user","title":"User","description":"Entity (person, organization, institution, etc.) requesting data or information with specified characteristics.","permalink":"/eo-glossary/terms/user"},{"id":"terms/user_engagement","title":"User Engagement","description":"Evidence-based practice of understanding user needs, challenges, and work environments to deliver useful, usable, and used products and services through ongoing mutual exchange.","permalink":"/eo-glossary/terms/user_engagement"},{"id":"terms/user_guide","title":"User Guide","description":"Documentation intended to assist users in using a particular product, service, or application.","permalink":"/eo-glossary/terms/user_guide"}],"unlisted":false}}')}}]);